export function validateST_TextRotation(value: unknown, path = 'ST_TextRotation'): ValidationResult {
  const issues: ValidationIssue[] = [];
  if (typeof value !== 'string') issues.push(issue(path, 'invalid-value', 'expected a string'));
  let valid = false;
  if (validateST_TextRotation_Anon(value, path).length === 0) valid = true;
  if (validateST_TextRotation_Anon2(value, path).length === 0) valid = true;
  if (!valid) issues.push(issue(path, "invalid-value", "value does not match any union member"));
  return issues;
}

export function validateST_TextRotation_Anon(value: unknown, path = 'ST_TextRotation_Anon'): ValidationResult {
  const issues: ValidationIssue[] = [];
  if (typeof value !== 'number' || !Number.isFinite(value)) issues.push(issue(path, 'invalid-value', 'expected a finite number'));
  if (typeof value === 'number' && value > 180) issues.push(issue(path, 'facet-violation', 'above maxInclusive'));
  return issues;
}

