export function validateCT_Authors(value: unknown, path = 'CT_Authors'): ValidationResult {
  const issues: ValidationIssue[] = [];
  if (value === null || typeof value !== 'object') return [issue(path, 'invalid-value', 'expected an object')];
  const v = value as Record<string, unknown>;
  if (!Array.isArray(v['author'])) {
  } else {
    for (let i = 0; i < (v['author'] as readonly unknown[]).length; i += 1) {
      issues.push(...validateST_Xstring((v['author'] as readonly unknown[])[i], path + '.author[' + i + ']'));
    }
  }
  return issues;
}

export function validateCT_AutoFilter(value: unknown, path = 'CT_AutoFilter'): ValidationResult {
  const issues: ValidationIssue[] = [];
  if (value === null || typeof value !== 'object') return [issue(path, 'invalid-value', 'expected an object')];
  const v = value as Record<string, unknown>;
  if (!Array.isArray(v['filterColumn'])) {
  } else {
    for (let i = 0; i < (v['filterColumn'] as readonly unknown[]).length; i += 1) {
      issues.push(...validateCT_FilterColumn((v['filterColumn'] as readonly unknown[])[i], path + '.filterColumn[' + i + ']'));
    }
  }
  if (v['sortState'] === undefined) {
  } else {
    issues.push(...validateCT_SortState(v['sortState'], path + '.sortState'));
  }
  if (v['extLst'] === undefined) {
  } else {
    issues.push(...validateCT_ExtensionList(v['extLst'], path + '.extLst'));
  }
  if (v['ref'] === undefined) {
  } else {
    issues.push(...validateST_Ref(v['ref'], path + '.ref'));
  }
  return issues;
}

export function validateCT_AutoSortScope(value: unknown, path = 'CT_AutoSortScope'): ValidationResult {
  const issues: ValidationIssue[] = [];
  if (value === null || typeof value !== 'object') return [issue(path, 'invalid-value', 'expected an object')];
  const v = value as Record<string, unknown>;
  if (v['pivotArea'] === undefined) {
    issues.push(issue(path + '.pivotArea', 'missing-required', 'required slot is absent'));
  } else {
    issues.push(...validateCT_PivotArea(v['pivotArea'], path + '.pivotArea'));
  }
  return issues;
}

export function validateCT_BookView(value: unknown, path = 'CT_BookView'): ValidationResult {
  const issues: ValidationIssue[] = [];
  if (value === null || typeof value !== 'object') return [issue(path, 'invalid-value', 'expected an object')];
  const v = value as Record<string, unknown>;
  if (v['extLst'] === undefined) {
  } else {
    issues.push(...validateCT_ExtensionList(v['extLst'], path + '.extLst'));
  }
  if (v['visibility'] === undefined) {
  } else {
    issues.push(...validateST_Visibility(v['visibility'], path + '.visibility'));
  }
  if (v['minimized'] === undefined) {
  } else {
    if (!validBuiltin(v['minimized'], 'xsd:boolean')) issues.push(issue(path + '.minimized', 'invalid-value', 'invalid xsd:boolean'));
  }
  if (v['showHorizontalScroll'] === undefined) {
  } else {
    if (!validBuiltin(v['showHorizontalScroll'], 'xsd:boolean')) issues.push(issue(path + '.showHorizontalScroll', 'invalid-value', 'invalid xsd:boolean'));
  }
  if (v['showVerticalScroll'] === undefined) {
  } else {
    if (!validBuiltin(v['showVerticalScroll'], 'xsd:boolean')) issues.push(issue(path + '.showVerticalScroll', 'invalid-value', 'invalid xsd:boolean'));
  }
  if (v['showSheetTabs'] === undefined) {
  } else {
    if (!validBuiltin(v['showSheetTabs'], 'xsd:boolean')) issues.push(issue(path + '.showSheetTabs', 'invalid-value', 'invalid xsd:boolean'));
  }
  if (v['xWindow'] === undefined) {
  } else {
    if (!validBuiltin(v['xWindow'], 'xsd:int')) issues.push(issue(path + '.xWindow', 'invalid-value', 'invalid xsd:int'));
  }
  if (v['yWindow'] === undefined) {
  } else {
    if (!validBuiltin(v['yWindow'], 'xsd:int')) issues.push(issue(path + '.yWindow', 'invalid-value', 'invalid xsd:int'));
  }
  if (v['windowWidth'] === undefined) {
  } else {
    if (!validBuiltin(v['windowWidth'], 'xsd:unsignedInt')) issues.push(issue(path + '.windowWidth', 'invalid-value', 'invalid xsd:unsignedInt'));
  }
  if (v['windowHeight'] === undefined) {
  } else {
    if (!validBuiltin(v['windowHeight'], 'xsd:unsignedInt')) issues.push(issue(path + '.windowHeight', 'invalid-value', 'invalid xsd:unsignedInt'));
  }
  if (v['tabRatio'] === undefined) {
  } else {
    if (!validBuiltin(v['tabRatio'], 'xsd:unsignedInt')) issues.push(issue(path + '.tabRatio', 'invalid-value', 'invalid xsd:unsignedInt'));
  }
  if (v['firstSheet'] === undefined) {
  } else {
    if (!validBuiltin(v['firstSheet'], 'xsd:unsignedInt')) issues.push(issue(path + '.firstSheet', 'invalid-value', 'invalid xsd:unsignedInt'));
  }
  if (v['activeTab'] === undefined) {
  } else {
    if (!validBuiltin(v['activeTab'], 'xsd:unsignedInt')) issues.push(issue(path + '.activeTab', 'invalid-value', 'invalid xsd:unsignedInt'));
  }
  if (v['autoFilterDateGrouping'] === undefined) {
  } else {
    if (!validBuiltin(v['autoFilterDateGrouping'], 'xsd:boolean')) issues.push(issue(path + '.autoFilterDateGrouping', 'invalid-value', 'invalid xsd:boolean'));
  }
  return issues;
}

