export function validateCT_Boolean(value: unknown, path = 'CT_Boolean'): ValidationResult {
  const issues: ValidationIssue[] = [];
  if (value === null || typeof value !== 'object') return [issue(path, 'invalid-value', 'expected an object')];
  const v = value as Record<string, unknown>;
  if (!Array.isArray(v['x'])) {
  } else {
    for (let i = 0; i < (v['x'] as readonly unknown[]).length; i += 1) {
      issues.push(...validateCT_X((v['x'] as readonly unknown[])[i], path + '.x[' + i + ']'));
    }
  }
  if (v['v'] === undefined) {
    issues.push(issue(path + '.v', 'missing-required', 'required attribute is absent'));
  } else {
    if (!validBuiltin(v['v'], 'xsd:boolean')) issues.push(issue(path + '.v', 'invalid-value', 'invalid xsd:boolean'));
  }
  if (v['u'] === undefined) {
  } else {
    if (!validBuiltin(v['u'], 'xsd:boolean')) issues.push(issue(path + '.u', 'invalid-value', 'invalid xsd:boolean'));
  }
  if (v['f'] === undefined) {
  } else {
    if (!validBuiltin(v['f'], 'xsd:boolean')) issues.push(issue(path + '.f', 'invalid-value', 'invalid xsd:boolean'));
  }
  if (v['c'] === undefined) {
  } else {
    issues.push(...validateST_Xstring(v['c'], path + '.c'));
  }
  if (v['cp'] === undefined) {
  } else {
    if (!validBuiltin(v['cp'], 'xsd:unsignedInt')) issues.push(issue(path + '.cp', 'invalid-value', 'invalid xsd:unsignedInt'));
  }
  return issues;
}

