export function validateCT_CacheSource(value: unknown, path = 'CT_CacheSource'): ValidationResult {
  const issues: ValidationIssue[] = [];
  if (value === null || typeof value !== 'object') return [issue(path, 'invalid-value', 'expected an object')];
  const v = value as Record<string, unknown>;
  if (v['content'] === undefined) {
  } else {
    if (v['content'] && typeof v['content'] === 'object') {
      const item = v['content'] as { kind?: unknown; value?: unknown };
      if (item.kind !== '$raw') {
        if (item.kind === 'worksheetSource') issues.push(...validateCT_WorksheetSource(item.value, path + '.content' + '.value'));
        if (item.kind === 'consolidation') issues.push(...validateCT_Consolidation(item.value, path + '.content' + '.value'));
        if (item.kind === 'extLst') issues.push(...validateCT_ExtensionList(item.value, path + '.content' + '.value'));
        if ('worksheetSource' !== item.kind && 'consolidation' !== item.kind && 'extLst' !== item.kind) issues.push(issue(path + '.content', 'invalid-value', 'unknown choice alternative'));
      }
    }
  }
  if (v['type'] === undefined) {
    issues.push(issue(path + '.type', 'missing-required', 'required attribute is absent'));
  } else {
    issues.push(...validateST_SourceType(v['type'], path + '.type'));
  }
  if (v['connectionId'] === undefined) {
  } else {
    if (!validBuiltin(v['connectionId'], 'xsd:unsignedInt')) issues.push(issue(path + '.connectionId', 'invalid-value', 'invalid xsd:unsignedInt'));
  }
  return issues;
}

