export function validateCT_Mdx(value: unknown, path = 'CT_Mdx'): ValidationResult {
  const issues: ValidationIssue[] = [];
  if (value === null || typeof value !== 'object') return [issue(path, 'invalid-value', 'expected an object')];
  const v = value as Record<string, unknown>;
  if (v['content'] === undefined) {
    issues.push(issue(path + '.content', 'missing-required', 'required slot is absent'));
  } else {
    if (v['content'] && typeof v['content'] === 'object') {
      const item = v['content'] as { kind?: unknown; value?: unknown };
      if (item.kind !== '$raw') {
        if (item.kind === 't') issues.push(...validateCT_MdxTuple(item.value, path + '.content' + '.value'));
        if (item.kind === 'ms') issues.push(...validateCT_MdxSet(item.value, path + '.content' + '.value'));
        if (item.kind === 'p') issues.push(...validateCT_MdxMemeberProp(item.value, path + '.content' + '.value'));
        if (item.kind === 'k') issues.push(...validateCT_MdxKPI(item.value, path + '.content' + '.value'));
        if ('t' !== item.kind && 'ms' !== item.kind && 'p' !== item.kind && 'k' !== item.kind) issues.push(issue(path + '.content', 'invalid-value', 'unknown choice alternative'));
      }
    }
  }
  if (v['n'] === undefined) {
    issues.push(issue(path + '.n', 'missing-required', 'required attribute is absent'));
  } else {
    if (!validBuiltin(v['n'], 'xsd:unsignedInt')) issues.push(issue(path + '.n', 'invalid-value', 'invalid xsd:unsignedInt'));
  }
  if (v['f'] === undefined) {
    issues.push(issue(path + '.f', 'missing-required', 'required attribute is absent'));
  } else {
    issues.push(...validateST_MdxFunctionType(v['f'], path + '.f'));
  }
  return issues;
}

