export function validateCT_PCDSDTCEntries(value: unknown, path = 'CT_PCDSDTCEntries'): ValidationResult {
  const issues: ValidationIssue[] = [];
  if (value === null || typeof value !== 'object') return [issue(path, 'invalid-value', 'expected an object')];
  const v = value as Record<string, unknown>;
  if (!Array.isArray(v['content'])) {
  } else {
    for (let i = 0; i < (v['content'] as readonly unknown[]).length; i += 1) {
      if ((v['content'] as readonly unknown[])[i] && typeof (v['content'] as readonly unknown[])[i] === 'object') {
        const item = (v['content'] as readonly unknown[])[i] as { kind?: unknown; value?: unknown };
        if (item.kind !== '$raw') {
          if (item.kind === 'm') issues.push(...validateCT_Missing(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 'n') issues.push(...validateCT_Number(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 'e') issues.push(...validateCT_Error(item.value, path + '.content[' + i + ']' + '.value'));
          if (item.kind === 's') issues.push(...validateCT_String(item.value, path + '.content[' + i + ']' + '.value'));
          if ('m' !== item.kind && 'n' !== item.kind && 'e' !== item.kind && 's' !== item.kind) issues.push(issue(path + '.content[' + i + ']', 'invalid-value', 'unknown choice alternative'));
        }
      }
    }
  }
  if (v['count'] === undefined) {
  } else {
    if (!validBuiltin(v['count'], 'xsd:unsignedInt')) issues.push(issue(path + '.count', 'invalid-value', 'invalid xsd:unsignedInt'));
  }
  return issues;
}

